{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group rule allows unrestricted ingress on RDP port",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "CRITICAL",
      "explanation": "Allowing unrestricted ingress (0.0.0.0/0) on port 3389 (RDP) exposes the resource to potential brute force attacks and unauthorized access from the internet."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/16\"] # Restrict to a private network or specific trusted IP range\n}",
  "fix_summary": "Restricted the CIDR block from 0.0.0.0/0 to 10.0.0.0/16 to limit access to a private network or trusted IP range, mitigating the risk of unauthorized access."
}
